std::once_flag wireloom_type_plugins_once;
void wireloom_initialize_type_plugins()
{
    std::call_once(wireloom_type_plugins_once, []
    {
        // Stage 1: create all struct types without inheritance.
        ::CorpusAggregates::wireloom_Base_type_context_instance().create_type();
        ::CorpusAggregates::wireloom_Recursive_type_context_instance().create_type();
        ::CorpusAggregates::wireloom_Composed_type_context_instance().create_type();

        // Stage 2: register metadata in dependency order; recursive collections use the existing type shell.
        ::CorpusAggregates::wireloom_Base_type_context_instance().add_members();
        ::CorpusAggregates::wireloom_Derived_type_context_instance().create_type();
        ::CorpusAggregates::wireloom_Derived_type_context_instance().add_members();
        ::CorpusAggregates::wireloom_Recursive_type_context_instance().add_members();
        ::CorpusAggregates::wireloom_Composed_type_context_instance().add_members();

        // Stage 3: create plugins only after every DynamicType is complete.
        ::CorpusAggregates::wireloom_Base_type_context_instance().create_type_plugin();
        ::CorpusAggregates::wireloom_Derived_type_context_instance().create_type_plugin();
        ::CorpusAggregates::wireloom_Recursive_type_context_instance().create_type_plugin();
        ::CorpusAggregates::wireloom_Composed_type_context_instance().create_type_plugin();
    });
}
